# description:
# The input grid consists of pixels with different colors. We will choose a random target color from the input.
# For each row and column, identify the maximal contiguous runs of that target color. 
# In the output grid, highlight these runs by preserving them, and set all other pixels to a background color (e.g., black).

def main(input_grid: np.ndarray) -> np.ndarray:
    # Select a target color randomly from the non-black colors in the input grid
    unique_colors = np.unique(input_grid)
    target_color = np.random.choice(list(filter(lambda c: c != Color.BLACK, unique_colors)))

    # Initialize the output grid with a background color (e.g., black)
    output_grid = np.full(input_grid.shape, Color.BLACK)

    # Process each row
    for i in range(input_grid.shape[0]):
        max_run_start, max_run_end = -1, -1
        current_run_start = -1

        for j in range(input_grid.shape[1]):
            if input_grid[i, j] == target_color:
                if current_run_start == -1:
                    current_run_start = j
            else:
                if current_run_start != -1:
                    if max_run_end == -1 or (j - current_run_start) > (max_run_end - max_run_start):
                        max_run_start, max_run_end = current_run_start, j
                    current_run_start = -1

        # Check if the last run is the maximal one
        if current_run_start != -1:
            if max_run_end == -1 or (input_grid.shape[1] - current_run_start) > (max_run_end - max_run_start):
                max_run_start, max_run_end = current_run_start, input_grid.shape[1]

        # Highlight the maximal run in the output grid
        if max_run_start != -1:
            output_grid[i, max_run_start:max_run_end] = target_color

    # Process each column
    for j in range(input_grid.shape[1]):
        max_run_start, max_run_end = -1, -1
        current_run_start = -1

        for i in range(input_grid.shape[0]):
            if input_grid[i, j] == target_color:
                if current_run_start == -1:
                    current_run_start = i
            else:
                if current_run_start != -1:
                    if max_run_end == -1 or (i - current_run_start) > (max_run_end - max_run_start):
                        max_run_start, max_run_end = current_run_start, i
                    current_run_start = -1

        # Check if the last run is the maximal one
        if current_run_start != -1:
            if max_run_end == -1 or (input_grid.shape[0] - current_run_start) > (max_run_end - max_run_start):
                max_run_start, max_run_end = current_run_start, input_grid.shape[0]

        # Highlight the maximal run in the output grid
        if max_run_start != -1:
            output_grid[max_run_start:max_run_end, j] = target_color

    return output_grid


def generate_input() -> np.ndarray:
