import numpy as np
from typing import *

# concepts:
# maximal_contiguous_runs, target_color_detection

# description:
# Identify the maximal contiguous runs of a specified target color in each row or column of the grid.
# Output a grid where these runs are highlighted with the target color, and all other cells are set to a background color.

def main(input_grid: np.ndarray) -> np.ndarray:
    target_color = None
    # Determine the target color by finding the color with the maximum contiguous run in any row or column
    max_run = 0

    for color in Color.NOT_BLACK:
        for row in input_grid:
            run_length = 0
            for cell in row:
                if cell == color:
                    run_length += 1
                else:
                    max_run = max(max_run, run_length)
                    if run_length == max_run:
                        target_color = color
                    run_length = 0
            max_run = max(max_run, run_length)
            if run_length == max_run:
                target_color = color

        for col in input_grid.T:
            run_length = 0
            for cell in col:
                if cell == color:
                    run_length += 1
                else:
                    max_run = max(max_run, run_length)
                    if run_length == max_run:
                        target_color = color
                    run_length = 0
            max_run = max(max_run, run_length)
            if run_length == max_run:
                target_color = color

    # Create an output grid with the background color
    output_grid = np.full(input_grid.shape, Color.BLACK)

    # Highlight the maximal contiguous runs of the target color
    for i, row in enumerate(input_grid):
        run_length = 0
        for j, cell in enumerate(row):
            if cell == target_color:
                run_length += 1
            else:
                if run_length == max_run:
                    output_grid[i, j-run_length:j] = target_color
                run_length = 0
        if run_length == max_run:
            output_grid[i, len(row)-run_length:len(row)] = target_color

    for j, col in enumerate(input_grid.T):
        run_length = 0
        for i, cell in enumerate(col):
            if cell == target_color:
                run_length += 1
            else:
                if run_length == max_run:
                    output_grid[i-run_length:i, j] = target_color
                run_length = 0
        if run_length == max_run:
            output_grid[len(col)-run_length:len(col), j] = target_color

    return output_grid


def generate_input() -> np.ndarray:
    # Randomly select a grid size between 4x4 and 8x8
    n, m = random.randint(4, 8), random.randint(4, 8)
    grid = np.full((n, m), Color.BLACK)

    # Choose a random target color and place several contiguous runs
    target_color = random.choice(Color.NOT_BLACK)
    other_colors = [color for color in Color.NOT_BLACK if color != target_color]

    # Create some maximal runs in random rows and columns
    for _ in range(random.randint(1, 3)):
        is_row = random.choice([True, False])
        if is_row:
            row = random.randint(0, n-1)
            start_col = random.randint(0, m-3)
            run_length = random.randint(2, m-start_col)
            grid[row, start_col:start_col+run_length] = target_color
        else:
            col = random.randint(0, m-1)
            start_row = random.randint(0, n-3)
            run_length = random.randint(2, n-start_row)
            grid[start_row:start_row+run_length, col] = target_color

    # Fill remaining cells with random colors
    for i in range(n):
        for j in range(m):
            if grid[i, j] == Color.BLACK:
                grid[i, j] = random.choice(other_colors)

    return grid
